import re
from dataclasses import dataclass, field
from typing import Optional

HEADING = re.compile(r"^## \[(?P<version>[^\]]+)\](?: - (?P<date>\d{4}-\d{2}-\d{2}))?\s*$")
# A comment, the whitespace before it, and any whitespace after it that would
# be left dangling at the end of the line.
COMMENT = re.compile(r"[ \t]*<!--.*?-->(?:[ \t]*$)?", re.DOTALL | re.MULTILINE)


@dataclass
class Release:
    version: str
    date: Optional[str]
    body: list = field(default_factory=list)


def parse_changelog(text):
    releases = []
    current = None
    text = COMMENT.sub("", "\n".join(text.splitlines()))
    for line in text.splitlines():
        if line.startswith("## "):
            match = HEADING.match(line)
            if match is None:
                current = None
                continue
            current = Release(match.group("version"), match.group("date"))
            releases.append(current)
        elif current is not None:
            current.body.append(line)
    return releases


def render_release(text, version):
    for release in parse_changelog(text):
        if release.version == version:
            lines = []
            for line in release.body:
                if not line.strip():
                    line = ""
                    if not lines or lines[-1] == "":
                        continue
                lines.append(line)
            while lines and lines[-1] == "":
                lines.pop()
            body = "\n".join(lines)
            title = f"{release.version} ({release.date})" if release.date else release.version
            return f"# {title}\n\n{body}\n"
    raise LookupError(version)

